P.write_text("from pathlib import Path\nimport ast,hashlib\nfrom qseries_v2.oracle_predictive_data.opd_036_live_production_boundary_contract import build as boundary\nOPD017='qseries_v2/oracle_predictive_data/opd_017_discovery_feature_primitive_materialization.py'\nOPD017_SHA='c0455590b2de0560552bdfd503dfbe0bf8a97a105617695581d2df0c56a00917'\ndef _scalars(x):\n    if isinstance(x,dict):\n        for v in x.values():\n            yield from _scalars(v)\n    elif isinstance(x,(list,tuple)):\n        for v in x:\n            yield from _scalars(v)\n    else:\n        yield x\ndef materialize_exact_live_tokens(root,state_at_t):\n    root=Path(root).resolve(); p=root/OPD017\n    if hashlib.sha256(p.read_bytes()).hexdigest()!=OPD017_SHA:\n        raise RuntimeError('frozen OPD-017 raw hash changed')\n    required=tuple(boundary(root)[0]['required_formula_tokens'])\n    obs=state_at_t.get('observations') or []; found=[]\n    for token in required:\n        provider,metric,value,label=ast.literal_eval(token.split('L:COND:',1)[1])\n        source=f\"source.crypto.condition.btc.{provider}.{metric}\"\n        row=next((x for x in obs if x.get('source_id')==source),None)\n        if row is None: continue\n        vals=list(_scalars(row.get('canonical_observation_json')))\n        numeric=any(isinstance(v,(int,float)) and not isinstance(v,bool) and float(v)==float(value) for v in vals)\n        text=any(str(v)==str(label) for v in vals)\n        if numeric and text: found.append(token)\n    return tuple(found)\n",encoding='utf-8')
py_compile.compile(str(P),doraise=True)
